-- The two checklists published on 2026-11-02: Before You Speak in Front of
-- People (Speaking) and The Hard Parts of Working for Yourself
-- (Self-Employment).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-02`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('before-you-speak-in-front-of-people', 'Before You Speak in Front of People', 'For the hour before you speak to a room, a meeting or a camera. It gets the opening rehearsed, the ending written down, the room walked, your breathing slowed, and a plan ready for the moment you lose your place.', 'Speaking', '["Say your first two sentences out loud ten times — the opening is where nerves do the most damage.", "Write your last line on a card — knowing how you land stops you trailing off.", "Walk the room before anyone arrives — a space you have stood in is less of an unknown.", "Breathe out longer than you breathe in for one minute — a slow out-breath settles a fast heart.", "Pick three friendly faces to look at — somewhere steady to land beats scanning for critics.", "Cut the slide you are least sure about — the part you doubt is the part that shows.", "Decide what you will do if you lose your place — a plan for the pause keeps it a pause.", "Keep water within reach and use it — a sip is a pause nobody in the room even notices.", "Plan one thing to do straight afterward — a walk or a coffee ends the adrenaline cleanly."]'::jsonb, 'as needed', array['Social Anxiety', 'Anxiety', 'Work']::text[], 1, '2026-11-02T16:00:00+00:00'::timestamptz),
  ('the-hard-parts-of-working-for-yourself', 'The Hard Parts of Working for Yourself', 'For anyone working for themselves, where there is no end to the day and nobody to compare notes with. It sets a finish time, puts a person in the day, separates the quiet-month money, and makes room for one full day off.', 'Self-Employment', '["Set a finish time and stop at it — work with no edge quietly takes the evening too.", "Put one actual conversation in the day — a whole day of your own company narrows how you think.", "Work somewhere that is not your bed — a spot you can leave is what ends the day.", "Keep a quiet-month fund apart from this month''s money — irregular income needs a buffer, not hope.", "Say no to the work you already know will go badly — the bad job costs you the good one.", "Invoice on a fixed day each week — a standing day is easier than remembering to ask.", "Find one person in the same trade to compare notes with — nobody else will tell you your rates are low.", "Take one full day off and tell someone you are taking it — a day off you announce is harder to give back.", "Write down what you earned this month — a real number ends the vague dread about it."]'::jsonb, 'weekly', array['Work', 'Boundaries', 'Loneliness']::text[], 1, '2026-11-02T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
